-- ONB-02 R7.4: register three one-off historical event contracts.
-- 074 is already deployed and remains byte-identical. No audit row/checkpoint DML.
-- Reapply is idempotent; the existing policy and projector function identities/ACLs remain.

CREATE OR REPLACE FUNCTION public.audit_event_policy(p_action TEXT,p_type TEXT)
RETURNS JSONB LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $policy$
 SELECT $json${"COMPANY_CREATED|company":{"company_id":"uuid","is_active":"bool","version":"int","actor_redacted":"bool"},"COMPANY_UPDATED|company":{"company_id":"uuid","is_active":"bool","version":"int","actor_redacted":"bool"},"COMPANY_PURGED|company":{"purged":"bool","actor_redacted":"bool"},"ESTABLISHMENT_CREATED|establishment":{"company_id":"uuid","is_active":"bool","actor_redacted":"bool"},"ESTABLISHMENT_UPDATED|establishment":{"company_id":"uuid","is_active":"bool","actor_redacted":"bool"},"ESTABLISHMENT_DELETED|establishment":{"company_id":"uuid","is_active":"bool","actor_redacted":"bool"},"COMPANY_TAX_PROFILE_UPDATED|company_tax_profile":{"company_id":"uuid","version":"int","actor_redacted":"bool"},"COMPANY_PRODUCT_PROFILE_UPDATED|company_product_profile":{"company_id":"uuid","is_active":"bool","actor_redacted":"bool"},"PLATFORM_ROLE_GRANTED|platform_user_role":{"role":["PLATFORM_ADMIN","TAXONOMY_CURATOR"],"actor_redacted":"bool"},"PLATFORM_ROLE_REVOKED|platform_user_role":{"role":["PLATFORM_ADMIN","TAXONOMY_CURATOR"],"actor_redacted":"bool"},"PLATFORM_ROLE_GRANTED|app_user":{"role":["PLATFORM_ADMIN","TAXONOMY_CURATOR"],"actor_redacted":"bool"},"PLATFORM_ROLE_REVOKED|app_user":{"role":["PLATFORM_ADMIN","TAXONOMY_CURATOR"],"actor_redacted":"bool"},"COLLECTION_FILTER_DRAFT_SAVED|collection_filter_policy":{"version":"int","revision":"int","actor_redacted":"bool"},"COLLECTION_FILTER_SIMULATION_REQUESTED|collection_filter_simulation":{"policyId":"uuid","version":"int","revision":"int","scope":["FULL_ARCHIVE","RECENT"],"reviewMode":["ALL","SAMPLE","NONE"],"actor_redacted":"bool"},"COLLECTION_FILTER_POLICY_APPROVED|collection_filter_policy":{"version":"int","revision":"int","simulationId":"uuid","actor_redacted":"bool"},"COLLECTION_FILTER_DIRECT_ADMIN_EDIT|collection_filter_policy":{"policyRevision":"int","action":["RULE_KEEP","RULE_DELETE","TERM_PUT","TERM_DELETE","ALIAS_PUT","ALIAS_DELETE","NEWTYPE_MERGE","NEWTYPE_KEEP"],"actor_redacted":"bool"},"COLLECTION_FILTER_DIRECT_RULE_CHANGED|collection_filter_type_rule":{"policyRevision":"int","mode":["KEEP_ALWAYS","KEEP_IF_TAX_TERM","EXCLUDE_UNLESS_STRONG","EXCLUDE_ALWAYS","EXCLUDE_ONCE"],"actor_redacted":"bool"},"COLLECTION_FILTER_DIRECT_PURGE|collection_filter_type_rule":{"deletedCount":"int","deletedIds":"uuids","mode":["KEEP_ALWAYS","KEEP_IF_TAX_TERM","EXCLUDE_UNLESS_STRONG","EXCLUDE_ALWAYS","EXCLUDE_ONCE"],"actor_redacted":"bool"},"L17_HIDDEN_PURGE|publications":{"deletedCount":"int","deletedIds":"uuids","policyId":"uuid","policyRevision":"int","mode":["RETENTION","EXCLUDE_ALWAYS"],"actor_redacted":"bool"},"L17_RULE_PURGE|publications":{"deletedCount":"int","deletedIds":"uuids","policyId":"uuid","policyRevision":"int","mode":["RETENTION","EXCLUDE_ALWAYS"],"actor_redacted":"bool"},"L18_PRESERVATION_RULES|collection_filter_policy":{"policyId":"uuid","policyRevision":"int","changedRuleCount":"int","addedStrongTerms":"int","actor_redacted":"bool"},"BASELINE_IMPORT_STARTED|taxonomy_baseline":{"manifestSha256":"sha256","derivationFingerprint":"sha256","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"BASELINE_IMPORT_FAILED|taxonomy_baseline":{"manifestSha256":"sha256","derivationFingerprint":"sha256","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"BASELINE_IMPORT_VALIDATED|taxonomy_baseline":{"manifestSha256":"sha256","derivationFingerprint":"sha256","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"BASELINE_IMPORT_COMMITTED|taxonomy_baseline":{"manifestSha256":"sha256","derivationFingerprint":"sha256","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"TAXONOMY_RELEASE_CREATED|taxonomy_baseline":{"manifestSha256":"sha256","derivationFingerprint":"sha256","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"TAXONOMY_SUCCESSOR_CREATED|taxonomy_release":{"manifestSha256":"sha256","snapshotSha256":"sha256","sourceReleaseId":"uuid","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"TAXONOMY_RELEASE_CREATED|taxonomy_release":{"manifestSha256":"sha256","snapshotSha256":"sha256","sourceReleaseId":"uuid","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"TAXONOMY_RELEASE_PUBLISHED|taxonomy_release":{"manifestSha256":"sha256","snapshotSha256":"sha256","sourceReleaseId":"uuid","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"TAXONOMY_SUCCESSOR_PUBLISHED|taxonomy_release":{"manifestSha256":"sha256","snapshotSha256":"sha256","sourceReleaseId":"uuid","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"TAXONOMY_RELEASE_VALIDATED|taxonomy_release":{"manifestSha256":"sha256","snapshotSha256":"sha256","sourceReleaseId":"uuid","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"TAXONOMY_CURATION_DRAFT_CREATED|taxonomy_curation":{"sourceReleaseId":"uuid","initialCuration":"bool","actor_redacted":"bool"},"TAXONOMY_CURATION_DIMENSION_UPDATED|taxonomy_curation":{"actor_redacted":"bool"},"TAXONOMY_CURATION_DIMENSION_RETIRED|taxonomy_curation":{"actor_redacted":"bool"},"TAXONOMY_CURATION_CONCEPT_CREATED|taxonomy_curation":{"actor_redacted":"bool"},"TAXONOMY_CURATION_CONCEPT_UPDATED|taxonomy_curation":{"actor_redacted":"bool"},"TAXONOMY_RUNTIME_SETTING_UPDATED|taxonomy_curation":{"actor_redacted":"bool"},"TAXONOMY_CURATION_GROUP_CREATED|taxonomy_curation":{"groupId":"uuid","actor_redacted":"bool"},"TAXONOMY_CURATION_GROUP_UPDATED|taxonomy_curation":{"groupId":"uuid","actor_redacted":"bool"},"TAXONOMY_CURATION_GROUP_DELETED|taxonomy_curation":{"groupId":"uuid","actor_redacted":"bool"},"TAXONOMY_CURATION_IMPORT|taxonomy_curation":{"rows":"int","created":"int","updated":"int","errors":"int","actor_redacted":"bool"},"TAXONOMY_CURATION_GRID_SAVE|taxonomy_curation":{"created":"int","updated":"int","retired":"int","groupsCreated":"int","groupsUpdated":"int","actor_redacted":"bool"},"TAXONOMY_CURATION_PUBLISHED|taxonomy_curation":{"snapshotSha256":"sha256","actor_redacted":"bool"},"F2_T02_ACTUACAO_INITIALIZED|taxonomy_curation":{"seedSha256":"sha256","actor_redacted":"bool"},"F2_T02_ACTUACAO_CNAE_ORIGINS_IMPORTED|taxonomy_curation":{"sourceSha256":"sha256","projectionSha256":"sha256","originCount":"int","publicationRequested":"bool","actor_redacted":"bool"},"TAXONOMY_F2_SUGGESTIONS_CHANGED|taxonomy_curation":{"productsCount":"int","ncmsCount":"int","actor_redacted":"bool"},"F2_TAB03_CNAE_ACTUACOES_CHANGED|taxonomy_curation":{"published":"bool","actor_redacted":"bool"},"OFFICIAL_CATALOG_IMPORTED|official_catalog_edition":{"editionId":"uuid","inserted":"int","updated":"int","total":"int","sourceSha256":"sha256","actor_redacted":"bool"},"PUBLICATION_TAG_CURATED|publication":{"action":["ADD","REMOVE","RESTORE"],"actor_redacted":"bool"},"PUBLICATION_PRESENTATION_REFRESHED|publication_version":{"savedPageSha256":"sha256","htmlChars":"int","effectiveUntil":"date","actor_redacted":"bool"},"TAXONOMY_V1_1_DRAFT_CREATED|taxonomy_release":{"sourceReleaseId":"uuid","actor_redacted":"bool"},"TAXONOMY_V1_1_PUBLISHED|taxonomy_release":{"artifactSha256":"sha256","actor_redacted":"bool"},"MERGE_RFB_NORMAS_DOU_HISTORICAL|publication":{"douPublicationId":"uuid","rfbPublicationId":"uuid","douIdentityHash":"sha256","rfbIdentityHash":"sha256","publicationId":"uuid","identityHash":"sha256","rfbExternalId":["153678","153667","153640","153663","153636","153191","153192","153193","153120","153046","153059"],"douExternalId":["2026-09-23:DO1:180:24398395","2026-09-23:DO1:180:24398396","2026-09-22:DO1:179:24392992","2026-09-22:DO1E:179-B:24391984","2026-09-21:DO1E:178-B:24386620","2026-08-31:DO1:164:24304745","2026-08-31:DO1:164:24302161","2026-08-31:DO1:164:24302159","2026-08-26:DO1:161:24286739","2026-08-24:DO1:159:24272929","2026-08-24:DO1E:159-B:24280394"],"origins":"rfb_dou_origins","actor_redacted":"bool"},"TAXONOMY_CURATION_SECTOR_ALIASES_CLEARED|taxonomy_curation":{"removedSynonyms":"int","rowsAffected":"int","actor_redacted":"bool"},"TAXONOMY_DRAFT_ORPHAN_RELATIONS_REMOVED|taxonomy_release":{"removedCount":"int","removedRelationIds":"uuids","preservedHistory":"bool","actor_redacted":"bool"}}$json$::jsonb -> (p_action||'|'||p_type)
$policy$;


-- A single fixed official-source pair is allowed only where the policy opts in.
CREATE OR REPLACE FUNCTION public.audit_project(p_action TEXT,p_type TEXT,p_json JSONB)
RETURNS JSONB LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public AS $project$
DECLARE v_rules JSONB:=public.audit_event_policy(p_action,p_type);
 v_out JSONB:='{}'; v_key TEXT; v_rule JSONB; v_value JSONB; v_ok BOOLEAN;
BEGIN
 IF v_rules IS NULL THEN
   RAISE EXCEPTION 'audit_event_not_registered' USING ERRCODE='23514';
 END IF;
 IF p_json IS NULL THEN RETURN NULL; END IF;
 IF jsonb_typeof(p_json)<>'object' THEN RETURN '{}'::jsonb; END IF;
 FOR v_key,v_rule IN SELECT key,value FROM jsonb_each(v_rules) LOOP
  v_value:=p_json->v_key; v_ok:=false;
  IF v_value IS NULL THEN CONTINUE; END IF;
  IF jsonb_typeof(v_rule)='array' THEN
    v_ok:=jsonb_typeof(v_value)='string' AND v_rule @> jsonb_build_array(v_value);
  ELSIF v_rule='"bool"'::jsonb THEN v_ok:=jsonb_typeof(v_value)='boolean';
  ELSIF v_rule='"int"'::jsonb THEN
    v_ok:=jsonb_typeof(v_value)='number' AND v_value::text ~ '^[0-9]{1,12}$';
  ELSIF v_rule='"uuid"'::jsonb THEN
    v_ok:=jsonb_typeof(v_value)='string' AND (v_value#>>'{}') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  ELSIF v_rule='"sha256"'::jsonb THEN
    v_ok:=jsonb_typeof(v_value)='string' AND (v_value#>>'{}') ~ '^[0-9a-fA-F]{64}$';
  ELSIF v_rule='"date"'::jsonb THEN
    v_ok:=jsonb_typeof(v_value)='string' AND (v_value#>>'{}') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$';
  ELSIF v_rule='"rfb_dou_origins"'::jsonb THEN
    v_ok:=v_value='["dou","rfb-normas"]'::jsonb;
  ELSIF v_rule='"uuids"'::jsonb AND jsonb_typeof(v_value)='array' THEN
    v_ok:=NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_value) e
      WHERE jsonb_typeof(e)<>'string' OR NOT (e#>>'{}') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$');
  END IF;
  IF v_ok THEN v_out:=v_out||jsonb_build_object(v_key,v_value); END IF;
 END LOOP;
 RETURN v_out;
END;
$project$;

